-- Gold layer DDL for stream: home-assistant-state
-- Generated by ndp-gold-ddl

CREATE SCHEMA IF NOT EXISTS gold;

-- Sync mode: Create if not exists
-- CA-SYNC-CHECK: schema=gold name=home_assistant_state_hourly
CREATE MATERIALIZED VIEW gold.home_assistant_state_hourly
WITH (timescaledb.continuous) AS
SELECT
    time_bucket('1 hour', event_time) AS bucket,
    ndp_id,
    COUNT(state) AS state_count,
    FIRST(state, event_time) AS state_first,
    LAST(state, event_time) AS state_last,
    COUNT(*) AS sample_count
FROM silver.state_events
GROUP BY bucket, ndp_id;

-- Refresh policy for gold.home_assistant_state_hourly
SELECT add_continuous_aggregate_policy('gold.home_assistant_state_hourly',
    start_offset => INTERVAL '4 hours',
    end_offset => INTERVAL '15 minutes',
    schedule_interval => INTERVAL '15 minutes',
    if_not_exists => TRUE
);

